export interface Address {
  line1: string;
  city: string;
  postcode: string;
}

export interface Customer {
  id: string;
  name: string;
  shipping?: Address;
}

export function greeting(c: Customer): string {
  return `Hello ${c.name}`;
}

/** The text printed on the parcel label. */
export function labelText(c: Customer): string {
  const a = c.shipping!;
  return [c.name, a.line1, `${a.city} ${a.postcode.toUpperCase()}`].join("\n");
}
